<?php require_once __DIR__.'/includes/bootstrap.php'; $id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT p.*,c.name category_name,u.name farmer_name FROM produce p JOIN categories c ON c.id=p.category_id JOIN users u ON u.id=p.farmer_id WHERE p.id=? AND p.status='approved'");$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);include __DIR__.'/includes/header.php';echo '<section class="section"><h1>Produce not found</h1><a href="catalogue.php">Return to catalogue</a></section>';include __DIR__.'/includes/footer.php';exit;}include __DIR__.'/includes/header.php'; ?>
<section class="section product-detail"><div class="detail-photo"><?php if($p['photo']): ?><img src="<?= e($p['photo']) ?>" alt="<?= e($p['name']) ?>"><?php else: ?><span>🌽</span><?php endif; ?></div><div><span class="eyebrow"><?= e($p['category_name']) ?></span><h1><?= e($p['name']) ?></h1><p><?= e($p['description']??'Fresh produce available directly from a local farmer.') ?></p><h2 class="detail-price">KSh <?= number_format((float)$p['price'],2) ?> <small>/ <?= e($p['unit']) ?></small></h2><p><b>Farmer:</b> <?= e($p['farmer_name']) ?><br><b>Location:</b> <?= e($p['location']) ?><br><b>Available:</b> <?= (int)$p['quantity'] ?> <?= e($p['unit']) ?></p><?php if(current_user() && current_user()['role']==='buyer'): ?><form method="post" action="cart.php"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="add"><input type="hidden" name="produce_id" value="<?= (int)$p['id'] ?>"><label>Quantity</label><input type="number" name="quantity" min="1" max="<?= (int)$p['quantity'] ?>" value="1" required><button class="btn" type="submit">Add to cart</button></form><?php elseif(!current_user()): ?><a class="btn" href="login.php">Log in to order</a><?php endif; ?></div></section><?php include __DIR__.'/includes/footer.php'; ?>